import{_ as r,o as a,c as e,ab as o}from"./chunks/framework.DCf1Sbhf.js";const l="/hubHooks/assets/retrieval.B0Ejxlah.png",u=JSON.parse('{"title":"Retrieval流程","description":"","frontmatter":{},"headers":[],"relativePath":"ai/langChain/retrieval.md","filePath":"ai/langChain/retrieval.md","lastUpdated":1773975001000}'),i={name:"ai/langChain/retrieval.md"};function n(s,t,d,p,h,g){return a(),e("div",null,[...t[0]||(t[0]=[o('<p>Retrieval直接翻译过来即“检索”</p><p><strong>Retrieval模块的设计意义</strong></p><ol><li>解决大模型的幻觉问题(答非所问) <strong>解决方案：</strong></li></ol><ul><li>RAG</li></ul><blockquote><p>RAG的优缺点</p><p>RAG的优点</p><ol><li>相比提示词工程，RAG有 更丰富的上下文和数据样本 ，可以不需要用户提供过多的背景描述，就能生 成比较符合用户预期的答案。</li><li>相比于模型微调，RAG可以提升问答内容的 <strong>时效性</strong> 和 <strong>可靠性</strong></li><li>在一定程度上保护了业务数据的 <strong>隐私性</strong> 。</li></ol><p>RAG的缺点</p><ol><li>由于每次问答都涉及外部系统数据检索，因此RAG的 <strong>响应时延</strong> 相对较高。</li><li>引用的外部知识数据会 消耗大量的<strong>模型Token</strong> 资源。</li></ol></blockquote><h1 id="retrieval流程" tabindex="-1">Retrieval流程 <a class="header-anchor" href="#retrieval流程" aria-label="Permalink to &quot;Retrieval流程&quot;">​</a></h1><p><img src="'+l+'" alt="retrieval"></p><h2 id="source-数据源" tabindex="-1">Source（数据源） <a class="header-anchor" href="#source-数据源" aria-label="Permalink to &quot;Source（数据源）&quot;">​</a></h2><p>指的是RAG架构中所外挂的知识库。</p><ol><li>原始数据源类型多样：如：视频、图片、文本、代码、文档等</li><li>形式的多样性： <ul><li>可以是上百个.csv文件，可以是上千个.json文件，也可以是上万个.pdf文件</li><li>可以是某一个业务流程外放的API，可以是某个网站的实时数据等</li></ul></li></ol><h2 id="load-加载" tabindex="-1">Load（加载） <a class="header-anchor" href="#load-加载" aria-label="Permalink to &quot;Load（加载）&quot;">​</a></h2><h3 id="文档加载器-document-loaders" tabindex="-1">文档加载器 Document Loaders <a class="header-anchor" href="#文档加载器-document-loaders" aria-label="Permalink to &quot;文档加载器 Document Loaders&quot;">​</a></h3><p>文档加载器（Document Loaders）负责将来自不同数据源的非结构化文本，加载到 <strong>内存</strong> ，成为 <strong>文档 (Document)对象</strong> 。 文档对象包含 <strong>文档内容</strong> 和相关 <strong>元数据信息</strong> ，例如TXT、CSV、HTML、JSON、Markdown、PDF，甚至 YouTube 视频转录等。</p><h2 id="transform-转换" tabindex="-1">Transform（转换） <a class="header-anchor" href="#transform-转换" aria-label="Permalink to &quot;Transform（转换）&quot;">​</a></h2><p>文档转换器(Document Transformers) 负责对加载的文档进行转换和处理，以便更好地适应下游任务的需求。</p><p>文档转换器提供了一致的接口（工具）来操作文档，主要包括以下几类：</p><ol><li><p>文本拆分器(Text Splitters) ：将长文本拆分成语义上相关的小块，以适应语言模型的上下文窗口限 制。</p></li><li><p>冗余过滤器(Redundancy Filters) ：识别并过滤重复的文档。</p></li><li><p>元数据提取器(Metadata Extractors) ：从文档中提取标题、语调等结构化元数据。</p></li><li><p>多语言转换器(Multi-lingual Transformers) ：实现文档的机器翻译。</p></li><li><p>对话转换器(Conversational Transformers) ：将非结构化对话转换为问答格式的文档。 总的来说，文档转换器是 LangChain 处理管道中非常重要的一个组件，它丰富了框架对文档的表示和 操作能力。</p></li></ol><h3 id="text-splitting-文档拆分" tabindex="-1">Text Splitting（文档拆分) <a class="header-anchor" href="#text-splitting-文档拆分" aria-label="Permalink to &quot;Text Splitting（文档拆分)&quot;">​</a></h3><p><strong>在构建RAG应用程序的整个流程中，拆分/分块是最具挑战性的环节之一，它显著影响检索效果</strong></p><ol><li><p>拆分/分块的必要性 ：前一个环节加载后的文档对象可以直接传入文档拆分器进行拆分，而文档切块 后才能 <strong>向量化</strong> 并存入数据库中。</p></li><li><p>文档拆分器的多样性 ：LangChain提供了丰富的文档拆分器，不仅能够切分普通文本，还能切分 Markdown、JSON、HTML、代码等特殊格式的文本。</p></li><li><p>拆分/分块的挑战性 ：实际拆分操作中需要处理许多细节问题， 不同类型的文本 、 不同的使用场景 都 需要采用不同的分块策略。</p><ul><li>可以按照 数据类型 进行切片处理，比如针对 文本类数据 ，可以直接按照字符、段落进行切 片； 代码类数据 则需要进一步细分以保证代码的功能性；</li><li>可以直接根据 token 进行切片处理</li></ul></li></ol><h2 id="embed-嵌入" tabindex="-1">Embed（嵌入） <a class="header-anchor" href="#embed-嵌入" aria-label="Permalink to &quot;Embed（嵌入）&quot;">​</a></h2><p>文档嵌入模型（Text Embedding Models）负责将 <strong>文本</strong> 转换为 <strong>向量表示</strong> ，即<strong>模型赋予了文本计算机可 理解的数值表示</strong>，使文本可用于向量空间中的各种运算，大大拓展了文本分析的可能性，是自然语言处 理领域非常重要的技术。</p><p>文本嵌入为 LangChain 中的问答、检索、推荐等功能提供了重要支持。具体为：</p><ol><li>语义匹配 ：通过计算两个文本的向量余弦相似度，判断它们在语义上的相似程度，实现语义匹配。</li><li>文本检索 ：通过计算不同文本之间的向量相似度，可以实现语义搜索，找到向量空间中最相似的文 本。</li><li>信息推荐 ：根据用户的历史记录或兴趣嵌入生成用户向量，计算不同信息的向量与用户向量的相似 度，推荐相似的信息。</li><li>知识挖掘 ：可以通过聚类、降维等手段分析文本向量的分布，发现文本之间的潜在关联，挖掘知 识。</li><li>自然语言处理 ：将词语、句子等表示为稠密向量，为神经网络等下游任务提供输入。</li></ol><h2 id="store-存储" tabindex="-1">Store（存储） <a class="header-anchor" href="#store-存储" aria-label="Permalink to &quot;Store（存储）&quot;">​</a></h2><p>LangChain 还支持把文本嵌入存储到<strong>向量存储(Vector Stores)<strong>或</strong>临时缓存</strong>，以避免需要重新计算它们。这里就出现了数 据库，支持这些嵌入的高效 <strong>存储</strong> 和 <strong>搜索</strong> 的需求。</p><p>典型的向量数据库</p><table tabindex="0"><thead><tr><th>向量数据库</th><th>描述</th></tr></thead><tbody><tr><td>Chroma</td><td>开源、免费的嵌入式数据库</td></tr><tr><td>FAISS</td><td>Meta出品，开源、免费，Facebook AI相似性搜索服务。（Facebook AI Similarity Search，Facebook AI 相似性搜索库） /fæs/</td></tr><tr><td>Milvus</td><td>用于存储、索引和管理由深度神经网络和其他ML模型产生的大量嵌入向量的数据库</td></tr><tr><td>Pinecone</td><td>具有广泛功能的向量数据库</td></tr><tr><td>Redis</td><td>基于Redis的检索器</td></tr></tbody></table><h2 id="retrieve-检索" tabindex="-1">Retrieve（检索） <a class="header-anchor" href="#retrieve-检索" aria-label="Permalink to &quot;Retrieve（检索）&quot;">​</a></h2><p>检索器（Retrievers）是一种用于 <strong>响应非结构化查询</strong> 的接口，它可以返回符合查询要求的文档。 LangChain 提供了一些常用的检索器，如 <strong>向量检索器 、 文档检索器 、 网站研究检索器</strong> 等。</p>',30)])])}const m=r(i,[["render",n]]);export{u as __pageData,m as default};
